// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: CodeMirror 6 SQL box for a table view's mini SQL runner (render.table_sql): highlighting
//          for polars SQL (PostgreSQL syntax, own short keyword list so column names like id or name
//          aren't keywords), Everforest colors, column completion for the table "self" (Tab completes,
//          as in a cell), and the run key from shortcuts.py (Shortcut.RUN_SQL). Usually one line; grows if you add more.
//          Also a SmashDb console's query editor (render.db_console_widget): given `schema`
//          ({table: columns}) instead of `columns`, it completes every table. Run sends the
//          selection when there is one, else the whole text. With editUrl: Alt+A inline chat (inline_edit.jsx).
// Usage: wrapped for Reflex by ui/editor.py (SqlEditor).
// ---------------------------------------------------------------------------
import React, { useMemo, useRef } from "react";
import CodeMirror from "@uiw/react-codemirror";
import { sql, SQLDialect } from "@codemirror/lang-sql";
import { autocompletion, closeCompletion } from "@codemirror/autocomplete";
import { EditorView, keymap } from "@codemirror/view";
import { Prec } from "@codemirror/state";
import { createTheme } from "@uiw/codemirror-themes";
import { tags as t } from "@lezer/highlight";
import { inlineEdit } from "./inline_edit.jsx";
import { c, completeOrIndent, completionOptions, editorSettings } from "./cell_editor.jsx";

// polars SQL: its keywords, functions and types only. CodeMirror's PostgreSQL dialect counts hundreds
// of words as keywords (self, id, name, sum, ...), which made nearly every word one color.
const PolarsSQL = SQLDialect.define({
  keywords: [
    "select distinct from where group by having order limit offset as on using join inner left right full outer",
    "cross natural semi anti lateral union all except intersect with recursive and or not in is null like ilike",
    "between case when then else end asc desc nulls first last exists over partition window qualify rows range",
    "unbounded preceding following current row filter within interval true false values explain show tables",
  ].join(" "),
  builtin: [
    "count sum avg mean median min max stddev stdev variance var first_value last_value array_agg string_agg",
    "abs round ceil ceiling floor sqrt cbrt ln log log2 log10 exp pow power mod sign pi degrees radians",
    "coalesce nullif greatest least if ifnull nvl cast try_cast lower upper length char_length octet_length",
    "concat concat_ws substr substring left right trim ltrim rtrim replace reverse starts_with ends_with strpos",
    "regexp_like regexp_replace split_part initcap date date_part extract strftime strptime now to_date",
    "row_number rank dense_rank lag lead unnest array_length array_contains array_get columns",
  ].join(" "),
  types: "int integer bigint smallint tinyint float double real decimal numeric varchar char text string boolean bool date time timestamp datetime interval uuid binary bytea",
  operatorChars: "+-*/<>=~!@#%^&|`?:",
});

// Everforest, with SQL's own roles: keywords blue, functions aqua, types yellow, strings green.
const sqlTheme = createTheme({
  theme: "dark",
  settings: editorSettings,
  styles: [
    { tag: t.keyword, color: c.blue },
    { tag: t.standard(t.name), color: c.aqua },
    { tag: t.typeName, color: c.yellow },
    { tag: [t.string, t.special(t.string)], color: c.green },
    { tag: [t.number, t.bool, t.null], color: c.purple },
    { tag: t.operator, color: c.orange },
    { tag: [t.punctuation, t.paren, t.squareBracket, t.brace], color: c.grey1 },
    { tag: [t.lineComment, t.blockComment, t.comment], color: c.grey1, fontStyle: "italic" },
    { tag: t.special(t.name), color: c.yellow },
    { tag: t.name, color: c.fg },
  ],
});

export function SqlEditor({ initialSql, columns, schema, placeholder, keys, editUrl, token, onRun, onSave }) {
  // the latest props, for the keymap built once
  const live = useRef({});
  const text = useRef(initialSql || "");
  // a table view gives its columns (the table is "self"); a console gives the whole schema
  const tables = schema || { self: columns || [] };
  live.current = { onRun, onSave, editUrl, token, tables };
  const tablesKey = JSON.stringify(tables);
  const save = () => { if (live.current.onSave) live.current.onSave(text.current); };

  // Alt+A inline chat, where editUrl is given (a SmashDb console). Built once: the extensions below
  // are rebuilt when the tables change, which would drop an open box.
  const chat = useMemo(() => inlineEdit(() => (
    { url: live.current.editUrl, key: keys?.inlineEdit, language: "sql",
      token: live.current.token, schema: live.current.tables })), []);

  const extensions = useMemo(() => [
    chat, // first, so its Tab / Esc win while a proposal is shown
    sql({ dialect: PolarsSQL, schema: tables, defaultTable: schema ? undefined : "self", upperCaseKeywords: false }),
    EditorView.lineWrapping,
    autocompletion(completionOptions),
    Prec.highest(keymap.of([{ key: keys?.complete || "Tab", run: completeOrIndent }, {
      key: keys?.run || "Mod-Enter",
      run: (view) => {
        closeCompletion(view);
        const { from, to } = view.state.selection.main;
        const picked = view.state.sliceDoc(from, to);
        save();
        live.current.onRun(picked.trim() ? picked : text.current);
        return true;
      },
    }])),
  ], [tablesKey]);

  return (
    <CodeMirror
      value={initialSql || ""}
      theme={sqlTheme}
      extensions={extensions}
      placeholder={placeholder || "select * from self"}
      basicSetup={{ lineNumbers: false, foldGutter: false, highlightActiveLine: false, highlightActiveLineGutter: false }}
      onChange={(value) => { text.current = value; }}
      onBlur={save}
    />
  );
}
